(()=>{const root=document.querySelector('.journey');if(!root)return;const reduced=matchMedia('(prefers-reduced-motion:reduce)'),images=[...root.querySelectorAll('.time-image')],copies=[...root.querySelectorAll('.journey-copy')],buttons=[...root.querySelectorAll('[data-chapter]')],bar=root.querySelector('.journey-track span');const clamp=v=>Math.max(0,Math.min(1,v)),ease=v=>{v=clamp(v);return v*v*(3-2*v)};let frame=0,manual=0;
function render(){frame=0;root.classList.toggle('is-scroll',!reduced.matches);const span=root.offsetHeight-root.querySelector('.journey-stage').offsetHeight,p=reduced.matches?manual/3:clamp(-root.getBoundingClientRect().top/Math.max(1,span)),position=p*3,active=Math.round(position);images.forEach((img,i)=>{img.style.opacity=i===0?1:ease((position-(i-1)-.4)/.2)});copies.forEach((el,i)=>{const weight=1-ease((Math.abs(position-i)-.28)/.2);el.style.opacity=weight;el.style.visibility=weight>.01?'visible':'hidden';el.inert=weight<.5;el.setAttribute('aria-hidden',String(weight<.5))});buttons.forEach((b,i)=>{if(i===active)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')});bar.style.transform=`scaleX(${p})`;root.dataset.progress=p.toFixed(3);root.dataset.time=String(active)}
function schedule(){if(!frame)frame=requestAnimationFrame(render)}buttons.forEach((b,i)=>b.addEventListener('click',()=>{if(reduced.matches){manual=i;render();return}const top=scrollY+root.getBoundingClientRect().top,span=root.offsetHeight-root.querySelector('.journey-stage').offsetHeight;scrollTo({top:top+span*i/3,behavior:'smooth'})}));addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule,{passive:true});reduced.addEventListener('change',schedule);render()})();
